body.script:
(async function() {
  const API = "https://pipe-a3ad1-default-rtdb.europe-west1.firebasedatabase.app";
  const resp = await fetch(API + "/blog/posts.json?orderBy=%22created%22");
  const data = await resp.json();
  const items = [];
  if (data) {
    const keys = Object.keys(data).reverse();
    for (const key of keys) {
      const p = data[key];
      const title = escapeXml((p.title || "").trim());
      const content = escapeXml((p.content || "").trim());
      const url = "https://pipe.lang/blog.html?post=" + key;
      const date = new Date(p.created).toUTCString();
      const excerpt = escapeXml(stripHtml(content).slice(0, 300));
      items.push(["  
",
        "    " + title + "",
        "    " + url + "",
        "    " + url + "",
        "    " + date + "",
        "    " + excerpt + "",
        "  "].join("\n"));
    }
  }
  const now = new Date().toUTCString();
  const rss = '\n' +
    '\n' +
    '\n' +
    '  Pipe Blog\n' +
    '  https://pipe.lang/blog.html\n' +
    '  Updates, tutorials, and deep dives into the Semantic Pipeline Runtime.\n' +
    '  en\n' +
    '  ' + now + '\n' +
    '  \n' +
    items.join("\n") + '\n' +
    '\n';
  document.open("text/xml");
  document.write(rss);
  document.close();
})();
function escapeXml(s) {
  return s.replace(/&/g,"&").replace(//g,">").replace(/"/g,""").replace(/'/g,"'");
}
function stripHtml(s) {
  const d = document.createElement("div");
  d.innerHTML = s;
  return d.textContent || d.innerText || "";
}
